#!/usr/bin/gjs
// SOURCE ONLY. Root must bind the baseline and review adoption before execution.
const { Gio, GLib } = imports.gi;
const SCHEMA = 'org.gnome.desktop.a11y.applications';
const KEY = 'screen-magnifier-enabled';
const BUS_NAME = 'org.gnome.Shell';
const CALL_TIMEOUT_MS = 3000;

function busCall(method, parameter, replyType) {
    return Gio.DBus.session.call_sync(
        'org.freedesktop.DBus', '/org/freedesktop/DBus',
        'org.freedesktop.DBus', method, new GLib.Variant('(s)', [parameter]),
        new GLib.VariantType(replyType), Gio.DBusCallFlags.NONE,
        CALL_TIMEOUT_MS, null).deep_unpack()[0];
}

function readText(path) {
    const [ok, bytes] = GLib.file_get_contents(path);
    if (!ok)
        throw new Error(`Cannot read ${path}`);
    return imports.byteArray.toString(bytes);
}

function startTicks(pid) {
    const stat = readText(`/proc/${pid}/stat`);
    const end = stat.lastIndexOf(')');
    if (end < 0)
        throw new Error('Malformed process stat');
    const value = stat.slice(end + 1).trim().split(/\s+/)[19];
    if (!value || !/^\d+$/.test(value))
        throw new Error('Missing process start ticks');
    return value;
}

function shellIdentity() {
    const owner = busCall('GetNameOwner', BUS_NAME, '(s)');
    const pid = busCall('GetConnectionUnixProcessID', owner, '(u)');
    return { owner, pid, startTicks: startTicks(pid) };
}

function requireIdentity(expected) {
    const actual = shellIdentity();
    if (actual.owner !== expected.owner || actual.pid !== expected.pid ||
        actual.startTicks !== expected.startTicks)
        throw new Error(`Shell identity mismatch: ${JSON.stringify(actual)}`);
    return actual;
}

function settingSnapshot(settings) {
    const user = settings.get_user_value(KEY);
    if (user !== null && user.get_type_string() !== 'b')
        throw new Error('Unexpected non-boolean user override');
    return {
        effective: settings.get_boolean(KEY),
        rawUserOverride: user === null ? null : user.print(true),
    };
}

function validateBaseline(baseline) {
    if (baseline.version !== 1 || baseline.schema !== SCHEMA || baseline.key !== KEY ||
        typeof baseline.effective !== 'boolean' ||
        ![null, 'true', 'false'].includes(baseline.rawUserOverride) ||
        typeof baseline.owner !== 'string' || !/^:\d+\.\d+$/.test(baseline.owner) ||
        baseline.pid !== 34063 || baseline.startTicks !== '38802')
        throw new Error('Baseline does not match the accepted Shell and boolean setting contract');
}

function writeReceiptBestEffort(path, value) {
    try {
        if (!GLib.file_set_contents(path, JSON.stringify(value, null, 2) + '\n'))
            throw new Error('Receipt write returned false');
    } catch (error) {
        try {
            printerr(`Receipt write failed: ${error.message}`);
        } catch (_) {
            // Failed evidence output must not veto a persisted-baseline guard.
        }
        return false;
    }
    return true;
}

function main() {
    const [mode, baselinePath, receiptPath, expectedOwner] = ARGV;
    if (!['capture', 'restore'].includes(mode) || !baselinePath || !receiptPath)
        throw new Error('Usage: capture|restore BASELINE RECEIPT [EXPECTED_OWNER]');
    const settings = new Gio.Settings({ schema_id: SCHEMA });

    if (mode === 'capture') {
        if (!expectedOwner || !/^:\d+\.\d+$/.test(expectedOwner))
            throw new Error('Capture requires the observed exact Shell unique owner');
        const expected = { owner: expectedOwner, pid: 34063, startTicks: '38802' };
        requireIdentity(expected);
        const snapshot = settingSnapshot(settings);
        if (snapshot.effective !== false || snapshot.rawUserOverride !== null || !settings.is_writable(KEY))
            throw new Error('Fresh capture differs from round12 Zoom-off/null/writable baseline');
        requireIdentity(expected);
        const baseline = { version: 1, schema: SCHEMA, key: KEY, ...expected, ...snapshot };
        // Baseline persistence failure rejects preparation. The immutable
        // controller still dispatches later physical keys unconditionally.
        if (!GLib.file_set_contents(baselinePath, JSON.stringify(baseline, null, 2) + '\n'))
            throw new Error('Baseline persistence failed');
        // Once the validated baseline persists, capture receipt failure must
        // not veto independent fallback arming by the prepare shell.
        writeReceiptBestEffort(receiptPath, { phase: 'capture', baseline });
        return;
    }

    const baseline = JSON.parse(readText(baselinePath));
    validateBaseline(baseline);
    const before = settingSnapshot(settings);
    // No log write occurs before the cleanup setting write.
    requireIdentity(baseline);
    if (baseline.rawUserOverride === null) {
        settings.reset(KEY);
    } else if (!settings.set_boolean(KEY, baseline.rawUserOverride === 'true')) {
        throw new Error('Restore set_boolean returned false');
    }
    Gio.Settings.sync();
    const after = settingSnapshot(settings);
    const ownerAfter = requireIdentity(baseline);
    const restored = after.effective === baseline.effective &&
        after.rawUserOverride === baseline.rawUserOverride;
    const recorded = writeReceiptBestEffort(receiptPath, {
        phase: 'restore', before, after, ownerAfter, restored,
        realTimeUs: GLib.get_real_time(), monotonicTimeUs: GLib.get_monotonic_time(),
    });
    if (!restored)
        throw new Error('Effective value or raw user override did not restore');
    if (!recorded)
        throw new Error('Setting restored, but completion receipt unavailable');
}

try {
    main();
} catch (error) {
    printerr(error.message);
    imports.system.exit(1);
}
ORIGINAL_ZOOM_SOURCE_0
cat > "$source_dir/finite-fallback.proposed.sh" <<'ORIGINAL_ZOOM_SOURCE_1'
#!/bin/sh
# SOURCE ONLY. Arguments are root-bound absolute paths in a private owned directory.
# Launch once as an independent process before physical UI input. No retries.
set -u
helper=$1
baseline=$2
receipt=$3
sleep 60
exec timeout --signal=TERM --kill-after=2s 12s gjs "$helper" restore "$baseline" "$receipt"
ORIGINAL_ZOOM_SOURCE_1
cat > "$source_dir/guard-runner.proposed.sh" <<'ORIGINAL_ZOOM_SOURCE_2'
#!/bin/sh
# Independent source-only supervisor. Evidence failures cannot veto restoration.
set -u
source_dir=$1
out=$2
timeout --signal=TERM --kill-after=2s 76s /bin/sh "$source_dir/finite-fallback.proposed.sh" "$source_dir/zoom-setting-cleanup.proposed.js" "$out/baseline.json" "$out/fallback-restore.json"
rc=$?
printf 'ORIGINAL_ZOOM_FALLBACK_EXIT=%s\n' "$rc"
printf '%s\n' "$rc" > "$out/fallback-exit.writing"
mv "$out/fallback-exit.writing" "$out/fallback-exit.txt"
exit "$rc"
ORIGINAL_ZOOM_SOURCE_2

sha256sum "$source_dir"/*
timeout --signal=TERM --kill-after=2s 12s gjs "$source_dir/zoom-setting-cleanup.proposed.js" capture "$out/baseline.json" "$out/capture.json" :1.17
setsid /bin/sh "$source_dir/guard-runner.proposed.sh" "$source_dir" "$out" > "$out/fallback.log" 2>&1 < /dev/null &
guard_pid=$!
printf '%s
' "$guard_pid" > "$out/fallback-pid.txt"
cat "/proc/$guard_pid/stat" > "$out/fallback-launch-stat.txt"
printf 'ORIGINAL_ZOOM_ARMED_PID=%s
' "$guard_pid"
if test -s "$out/capture.json"; then
  printf 'ORIGINAL_ZOOM_CAPTURE_RECEIPT_PRESENT
'
else
  printf 'ORIGINAL_ZOOM_CAPTURE_RECEIPT_MISSING_BASELINE_PERSISTED_FALLBACK_ARMED
'
fi
set +e
cat "$out/baseline.json" "$out/capture.json" "$out/fallback-launch-stat.txt"
printf 'ORIGINAL_ZOOM_PREPARE_COLLECTION_COMPLETE
'
ORIGINAL_ZOOM_ACTION_SOURCE
rc=$?
printf 'ORIGINAL_ZOOM_WHOLE_EXIT=prepare:%s
' "$rc"
date -u +%FT%T.%N
exit "$rc"
